async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  if (!sessionStore?.listFor) {
    sendSessionList(ws, []);
    return;
  }
  try {
    const summaries = await sessionStore.listFor(session.userId, listOptionsFrom(message));
    sendSessionList(ws, summaries.map(toSummaryFrame));
  } catch (error) {
    const detail = error instanceof Error ? error.message : String(error);
    log.error('ws', 'session list failed', {userId: session.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list sessions');
  }
}

function listOptionsFrom(message: ListSessionsMessage): SessionListOptions {
  const options: SessionListOptions = {};
  if (message.limit !== undefined) options.limit = message.limit;
  if (message.before !== undefined) options.before = message.before;
  return options;
}

function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: summary.createdAt.toISOString(),
    updatedAt: summary.updatedAt.toISOString(),
    entryCount: summary.entryCount,
  };
}
